/* =============================================================================
 * SUMMARISE RUN - POVO AI Guidance, Nightly Guidance Refresh v1
 *
 * Both HTTP nodes continue on error (after their own retries), so this node
 * always runs and reports both jobs. If either job failed it throws with the
 * summary as the message, so the execution shows as failed in the n8n
 * executions list. There is no email or chat alerting (out of scope).
 *
 * Backend responses (docs/ARCHITECTURE.md section 5):
 *   refresh-guidance -> {run_id, territories, snapshot_date}
 *   purge-ai-cache   -> {deleted}
 * Mosaic-style envelopes ({data: {...}}) are unwrapped as well.
 * ========================================================================== */
const pick = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    return j.data && typeof j.data === 'object' && !Array.isArray(j.data) ? Object.assign({}, j, j.data) : j;
  } catch (e) {
    return { error: { message: 'node did not run: ' + nodeName } };
  }
};
const errText = (j) => {
  if (!j || !j.error) return '';
  const e = j.error;
  return String((e && (e.message || e.description)) || e).replace(/\s+/g, ' ').slice(0, 300);
};

const refresh = pick('Refresh Guidance');
const purge = pick('Purge AI Cache');
const refreshErr = errText(refresh);
const purgeErr = errText(purge);

const summary = {
  ok: !refreshErr && !purgeErr,
  finished_at: $now.setZone('America/New_York').toISO(),
  refresh_guidance: refreshErr
    ? { ok: false, error: refreshErr }
    : { ok: true, run_id: refresh.run_id || null, territories: refresh.territories === undefined ? null : refresh.territories, snapshot_date: refresh.snapshot_date || null },
  purge_ai_cache: purgeErr
    ? { ok: false, error: purgeErr }
    : { ok: true, deleted: purge.deleted === undefined ? null : purge.deleted },
};

summary.message = [
  refreshErr
    ? 'Guidance refresh FAILED: ' + refreshErr
    : 'Guidance refreshed for ' + (summary.refresh_guidance.territories ?? '?') + ' territories (snapshot ' + (summary.refresh_guidance.snapshot_date || '?') + ', run ' + (summary.refresh_guidance.run_id || '?') + ').',
  purgeErr
    ? 'AI cache purge FAILED: ' + purgeErr
    : 'AI cache purge removed ' + (summary.purge_ai_cache.deleted ?? '?') + ' expired rows.',
].join(' ');

if (!summary.ok) throw new Error(summary.message);
return [{ json: summary }];
